# 多文件导出：每个已连接的 CSV/PNG 导入接口各写出一个文件
import os
import base64
import binascii
import re as _re_mod

try:
    _json_input = json
except NameError:
    _json_input = None
import json as _json_module

out_dir = {{folder}}
if out_dir is None or not os.path.isdir(out_dir):
    _fallback_dir = os.path.join(os.path.expanduser('~'), 'Desktop', 'MM')
    if os.path.isdir(_fallback_dir):
        out_dir = _fallback_dir
    else:
        raise RuntimeError('请先在参数区选择有效的导出文件夹（默认导出到桌面\MM 也不存在）')

try:
    _data_input = data
except NameError:
    _data_input = None
try:
    _image_input = image
except NameError:
    _image_input = None

_csv_names = {{fileBases}}
if not isinstance(_csv_names, list):
    _csv_names = []
_cleaned_csv_names = []
for _n in _csv_names:
    if isinstance(_n, str) and _n.strip():
        _clean = _re_mod.sub(r'[\\/:*?"<>|]', '_', _n.strip()).strip()
        _cleaned_csv_names.append(_clean if _clean else None)
    else:
        _cleaned_csv_names.append(None)

def _items(_value):
    if _value is None:
        return []
    if isinstance(_value, (list, tuple)):
        return [_item for _item in _value if _item is not None]
    return [_value]

def _available_path(_filename):
    _stem, _ext = os.path.splitext(_filename)
    _candidate = os.path.join(out_dir, _filename)
    _number = 1
    while os.path.exists(_candidate):
        _candidate = os.path.join(out_dir, _stem + ' (' + str(_number) + ')' + _ext)
        _number += 1
    return _candidate

_data_items = _items(_data_input)
_image_items = _items(_image_input)
_json_items = _items(_json_input)
if not _data_items and not _image_items and not _json_items:
    raise RuntimeError('没有可导出的内容：CSV、PNG 或 JSON 至少连接一个即可')

_prepared_csv = []
for _index, _item in enumerate(_data_items, start=1):
    if isinstance(_item, bytes):
        try:
            _text = _item.decode('utf-8-sig')
        except UnicodeDecodeError:
            _text = _item.decode('gbk')
    elif isinstance(_item, str):
        _text = _item
    elif hasattr(_item, 'to_csv'):
        _text = _item.to_csv(index=False)
    else:
        raise RuntimeError('第' + str(_index) + '个 CSV 输入必须是文本、字节或数据表')
    _prepared_csv.append(_text.lstrip('\ufeff'))

_prepared_png = []
for _index, _item in enumerate(_image_items, start=1):
    if isinstance(_item, bytes):
        _png = _item
    elif isinstance(_item, str):
        _encoded = _item.split(',', 1)[-1] if _item.strip().startswith('data:') else _item.strip()
        try:
            _png = base64.b64decode(_encoded, validate=True)
        except (binascii.Error, ValueError):
            raise RuntimeError('第' + str(_index) + '个 PNG 输入不是有效的图片数据')
    else:
        raise RuntimeError('第' + str(_index) + '个 PNG 输入格式不支持')
    _prepared_png.append(_png)

_saved = []
for _index, _text in enumerate(_prepared_csv, start=1):
    if _index - 1 < len(_cleaned_csv_names) and _cleaned_csv_names[_index - 1]:
        _name = _cleaned_csv_names[_index - 1] + '.csv'
    else:
        _name = '导出数据.csv' if len(_prepared_csv) == 1 else '导出数据_' + str(_index) + '.csv'
    _path = _available_path(_name)
    with open(_path, 'w', encoding='utf-8-sig', newline='') as _file:
        _file.write(_text)
    _saved.append(os.path.basename(_path))

for _index, _png in enumerate(_prepared_png, start=1):
    _name = '导出图片.png' if len(_prepared_png) == 1 else '导出图片_' + str(_index) + '.png'
    _path = _available_path(_name)
    with open(_path, 'wb') as _file:
        _file.write(_png)
    _saved.append(os.path.basename(_path))

_json_prepared = []
for _index, _item in enumerate(_json_items, start=1):
    if isinstance(_item, (dict, list)):
        _json_prepared.append(_item)
    else:
        raise RuntimeError('第 ' + str(_index) + ' 个 JSON 输入必须是对象或数组')

for _index, _item in enumerate(_json_prepared, start=1):
    _name = '导出数据.json' if len(_json_prepared) == 1 else '导出数据_' + str(_index) + '.json'
    _path = _available_path(_name)
    with open(_path, 'w', encoding='utf-8') as _file:
        _json_module.dump(_item, _file, ensure_ascii=False, indent=2)
    _saved.append(os.path.basename(_path))

return '已导出 ' + str(len(_saved)) + ' 个文件：' + '、'.join(_saved)
